from PIL import Image
import numpy as np
for fn, centers in [('practice_1/last/practice_cam.jpg',[335]),('practice_2/last/practice_cam.jpg',[172,397])]:
 a=np.array(Image.open('/app/output/'+fn).convert('RGB'))
 print(fn,a.shape)
 for v in (500,600,700):
  vals=np.mean(a[v,:,:],axis=1)<80
  runs=[]; st=None
  for u,z in enumerate(list(vals)+[False]):
   if z and st is None:st=u
   if not z and st is not None:
    if any(abs((st+u-1)/2-c)<70 for c in centers):runs.append((st,u-1,u-st))
    st=None
  print(v,runs)
